// A tiny pretend server for your tests. It answers fetch() the way your Express API does,
// so the tests never need your real server, your database, or a sign-in.
import { vi } from 'vitest'

export type ApiIssue = {
  _id: string
  title: string
  description: string
  stepsToReproduce: string
  priority: 'low' | 'medium' | 'high'
  status: 'open' | 'in-progress' | 'closed'
  classification: string
  author: { userId: string; fullName: string }
  assignedTo?: { userId: string; fullName: string }
  createdOn: string
}

export function makeIssue(n: number, overrides: Partial<ApiIssue> = {}): ApiIssue {
  return {
    _id: String(n).padStart(24, '0'),
    title: `Issue number ${n}`,
    description: `Description ${n}`,
    stepsToReproduce: `Steps ${n}`,
    priority: 'medium',
    status: 'open',
    classification: 'unclassified',
    author: { userId: 'u-eve', fullName: 'Eve Developer' },
    createdOn: new Date(Date.UTC(2026, 9, n)).toISOString(),
    ...overrides,
  }
}

export const sampleApiIssues: ApiIssue[] = [
  makeIssue(1, { title: 'Login button does nothing', status: 'open', priority: 'high' }),
  makeIssue(2, { title: 'Typo on the home page', status: 'closed', priority: 'low' }),
  makeIssue(3, { title: 'Search is slow on big lists', status: 'in-progress', priority: 'medium' }),
  makeIssue(4, { title: 'Footer links are broken', status: 'open', priority: 'low' }),
]

export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  })
}

export type SeenRequest = { method: string; url: string; body: unknown }

type FakeApiOptions = {
  // Make one kind of request fail, for example { 'DELETE /issues/000000000000000000000001': 403 }
  failures?: Record<string, number | Response>
}

// Replaces the global fetch with a pretend server that remembers issues in memory.
export function installFakeApi(initial: ApiIssue[] = sampleApiIssues, options: FakeApiOptions = {}) {
  const issues: ApiIssue[] = initial.map((i) => ({ ...i }))
  const seen: SeenRequest[] = []
  let counter = 100

  const fetchMock = vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(input)
    const method = (init?.method ?? 'GET').toUpperCase()
    const body = typeof init?.body === 'string' ? (JSON.parse(init.body) as Record<string, unknown>) : undefined
    seen.push({ method, url, body })

    const failure = options.failures?.[`${method} ${url}`]
    if (failure instanceof Response) return failure.clone()
    if (typeof failure === 'number') {
      const errorText = failure === 403 ? 'Your role may not do that' : failure === 401 ? 'Sign in required' : 'Server trouble'
      return jsonResponse({ error: errorText }, failure)
    }

    const path = url.split('?')[0] ?? url
    const parts = path.split('/').filter(Boolean) // ['issues', id?, 'status'?]
    if (parts[0] !== 'issues') return jsonResponse({ error: 'Not found' }, 404)
    const id = parts[1]
    const found = id ? issues.find((i) => i._id === id) : undefined

    if (method === 'GET' && !id) {
      // Understands the same query string as your API: q, status, priority, sort, page, limit.
      const query = new URLSearchParams(url.includes('?') ? url.slice(url.indexOf('?') + 1) : '')
      const q = query.get('q')?.toLowerCase()
      let list = issues.filter(
        (i) =>
          (!query.get('status') || i.status === query.get('status')) &&
          (!query.get('priority') || i.priority === query.get('priority')) &&
          (!q || `${i.title} ${i.description}`.toLowerCase().includes(q)),
      )
      const sort = query.get('sort')
      if (sort) {
        const direction = sort.startsWith('-') ? -1 : 1
        list = [...list].sort((a, b) => (a.createdOn < b.createdOn ? -1 : a.createdOn > b.createdOn ? 1 : 0) * direction)
      }
      const limit = Number(query.get('limit') ?? 20)
      const page = Number(query.get('page') ?? 1)
      return jsonResponse(list.slice((page - 1) * limit, page * limit))
    }
    if (method === 'GET' && id) return found ? jsonResponse(found) : jsonResponse({ error: 'Issue not found' }, 404)
    if (method === 'POST' && !id) {
      const created: ApiIssue = {
        _id: String(counter++).padStart(24, '0'),
        title: String(body?.title ?? ''),
        description: String(body?.description ?? ''),
        stepsToReproduce: String(body?.stepsToReproduce ?? ''),
        priority: (body?.priority as ApiIssue['priority']) ?? 'medium',
        status: 'open',
        classification: 'unclassified',
        author: { userId: 'u-eve', fullName: 'Eve Developer' },
        createdOn: new Date().toISOString(),
      }
      issues.push(created)
      return jsonResponse(created, 201)
    }
    if (!found) return jsonResponse({ error: 'Issue not found' }, 404)
    if (method === 'PATCH' && parts[2] === 'status') {
      found.status = body?.status as ApiIssue['status']
      return jsonResponse(found)
    }
    if (method === 'PATCH') {
      Object.assign(found, body)
      return jsonResponse(found)
    }
    if (method === 'DELETE') {
      issues.splice(issues.indexOf(found), 1)
      return new Response(null, { status: 204 })
    }
    return jsonResponse({ error: 'Not found' }, 404)
  })

  vi.stubGlobal('fetch', fetchMock)
  return { issues, seen, fetchMock }
}
